import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:shamsi_date/shamsi_date.dart';
import 'package:flutter_local_notifications/flutter_local_notifications.dart';
import 'package:timezone/data/latest.dart' as tzdata;
import 'package:timezone/timezone.dart' as tz;

final FlutterLocalNotificationsPlugin notifications = FlutterLocalNotificationsPlugin();
String jdate(DateTime d){final j=Gregorian.fromDateTime(d).toJalali();return '${j.year}/${j.month.toString().padLeft(2,'0')}/${j.day.toString().padLeft(2,'0')}';}
String jtime(DateTime d)=>'${d.hour.toString().padLeft(2,'0')}:${d.minute.toString().padLeft(2,'0')}';
String uid()=>DateTime.now().microsecondsSinceEpoch.toString();

Future<void> initNotifications() async {tzdata.initializeTimeZones();tz.setLocalLocation(tz.getLocation('Asia/Tehran'));const android=AndroidInitializationSettings('@mipmap/ic_launcher');const settings=InitializationSettings(android:android);await notifications.initialize(settings);final a=notifications.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>();await a?.requestNotificationsPermission();}
Future<void> scheduleReminder(int id,String title,String body,DateTime when) async {if(!when.isAfter(DateTime.now()))return;const android=AndroidNotificationDetails('arvin_reminders','یادآوری‌های آروین',channelDescription:'یادآوری کارها و پیگیری‌های آروین',importance:Importance.high,priority:Priority.high);await notifications.zonedSchedule(id,title:'آروین',body:body,scheduledDate:tz.TZDateTime.from(when,tz.local),notificationDetails:const NotificationDetails(android:android),androidScheduleMode:AndroidScheduleMode.inexactAllowWhileIdle,payload:id.toString());}

class Follow {String text;DateTime at;DateTime? reminder;Follow(this.text,this.at,{this.reminder});Map<String,dynamic>toJson()=>{'text':text,'at':at.toIso8601String(),'reminder':reminder?.toIso8601String()};factory Follow.fromJson(Map<String,dynamic>x)=>Follow(x['text']??'',DateTime.parse(x['at']),reminder:x['reminder']==null?null:DateTime.parse(x['reminder']));}
class Entry {String id,title,description,category;DateTime date;DateTime? reminder;bool task,archived,trash,tracking;List<String>tags;List<Follow>follows;Entry({required this.id,required this.title,required this.description,required this.category,required this.date,this.reminder,required this.task,required this.tags,required this.follows,this.archived=false,this.trash=false,this.tracking=false});Map<String,dynamic>toJson()=>{'id':id,'title':title,'description':description,'category':category,'date':date.toIso8601String(),'reminder':reminder?.toIso8601String(),'task':task,'tags':tags,'follows':follows.map((e)=>e.toJson()).toList(),'archived':archived,'trash':trash,'tracking':tracking};factory Entry.fromJson(Map<String,dynamic>x)=>Entry(id:x['id']??uid(),title:x['title']??'',description:x['description']??'',category:x['category']??'عمومی',date:DateTime.parse(x['date']),reminder:x['reminder']==null?null:DateTime.parse(x['reminder']),task:x['task']??false,tags:List<String>.from(x['tags']??[]),follows:(x['follows']as List? ??[]).map((e)=>Follow.fromJson(Map<String,dynamic>.from(e))).toList(),archived:x['archived']??false,trash:x['trash']??false,tracking:x['tracking']??false);}

void main() async {WidgetsFlutterBinding.ensureInitialized();await initNotifications();runApp(const ArvinApp());}
class ArvinApp extends StatefulWidget{const ArvinApp({super.key});@override State<ArvinApp>createState()=>_ArvinAppState();}
class _ArvinAppState extends State<ArvinApp>{bool dark=false;@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'آروین',theme:ThemeData(useMaterial3:true,fontFamily:'Vazirmatn',colorSchemeSeed:Colors.indigo),darkTheme:ThemeData(useMaterial3:true,fontFamily:'Vazirmatn',brightness:Brightness.dark,colorSchemeSeed:Colors.indigo),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:Directionality(textDirection:TextDirection.rtl,child:Home(toggle:()=>setState(()=>dark=!dark))));}

class Home extends StatefulWidget{final VoidCallback toggle;const Home({super.key,required this.toggle});@override State<Home>createState()=>_HomeState();}
class _HomeState extends State<Home>{List<Entry>items=[];List<String>cats=['عمومی'];String filter='همه',sort='آخرین وارده',query='';bool reverse=false;@override void initState(){super.initState();load();}Future<void>load()async{final p=await SharedPreferences.getInstance();final s=p.getString('arvin');if(s!=null)items=(jsonDecode(s)as List).map((e)=>Entry.fromJson(Map<String,dynamic>.from(e))).toList();cats=p.getStringList('cats')??['عمومی'];if(mounted)setState((){});}Future<void>save()async{final p=await SharedPreferences.getInstance();await p.setString('arvin',jsonEncode(items.map((e)=>e.toJson()).toList()));await p.setStringList('cats',cats);}bool today(DateTime d){final n=DateTime.now();return d.year==n.year&&d.month==n.month&&d.day==n.day;}List<Entry>get shown{var x=items.where((e)=>!e.trash).where((e){if(filter=='یادداشت‌ها')return !e.task&&!e.archived;if(filter=='کارها')return e.task&&!e.archived;if(filter=='امروز')return today(e.date)&&!e.archived;if(filter=='آینده')return e.date.isAfter(DateTime.now())&&!e.archived;if(filter=='عقب‌افتاده')return e.date.isBefore(DateTime.now())&&!today(e.date)&&!e.archived;if(filter=='بایگانی')return e.archived;return !e.archived;}).where((e)=>query.isEmpty||'${e.title} ${e.description} ${e.category} ${e.tags.join(" ")}'.contains(query)).toList();x.sort((a,b){final z=sort=='عنوان'?a.title.compareTo(b.title):sort=='تاریخ'?a.date.compareTo(b.date):a.date.compareTo(b.date);return reverse?z:-z;});return x;}
void edit({Entry? old,bool task=true}){final t=TextEditingController(text:old?.title??''),d=TextEditingController(text:old?.description??''),g=TextEditingController(text:old?.tags.join(', ')??'');String cat=old?.category??cats.first;DateTime date=old?.date??DateTime.now();DateTime? rem=old?.reminder;showModalBottomSheet(context:context,isScrollControlled:true,builder:(_)=>StatefulBuilder(builder:(c,set)=>Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(c).viewInsets.bottom),child:SingleChildScrollView(padding:const EdgeInsets.all(20),child:Column(children:[Text(old==null?'ایجاد ${task?'کار':'یادداشت'}':'ویرایش',style:Theme.of(c).textTheme.titleLarge),TextField(controller:t,decoration:const InputDecoration(labelText:'عنوان *')),TextField(controller:d,maxLines:3,decoration:const InputDecoration(labelText:'توضیحات')),DropdownButtonFormField<String>(value:cat,items:cats.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>set(()=>cat=v??cat),decoration:const InputDecoration(labelText:'دسته‌بندی')),TextField(controller:g,decoration:const InputDecoration(labelText:'تگ‌ها')),ListTile(title:Text('تاریخ: ${jdate(date)}'),trailing:const Icon(Icons.calendar_month),onTap:()async{final v=await showDatePicker(context:c,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:date);if(v!=null)set(()=>date=DateTime(v.year,v.month,v.day,date.hour,date.minute));}),ListTile(title:Text('ساعت: ${jtime(date)}'),trailing:const Icon(Icons.access_time),onTap:()async{final v=await showTimePicker(context:c,initialTime:TimeOfDay.fromDateTime(date));if(v!=null)set(()=>date=DateTime(date.year,date.month,date.day,v.hour,v.minute));}),ListTile(leading:const Icon(Icons.notifications_active_outlined),title:Text(rem==null?'افزودن یادآوری':'یادآوری: ${jdate(rem!)} ${jtime(rem!)}'),onTap:()async{final day=await showDatePicker(context:c,firstDate:DateTime.now(),lastDate:DateTime(2100),initialDate:rem??DateTime.now());if(day==null)return;final tm=await showTimePicker(context:c,initialTime:TimeOfDay.fromDateTime(rem??DateTime.now()));if(tm!=null)set(()=>rem=DateTime(day.year,day.month,day.day,tm.hour,tm.minute));},trailing:rem==null?null:IconButton(icon:const Icon(Icons.clear),onPressed:()=>set(()=>rem=null))),FilledButton(onPressed:()async{if(t.text.trim().isEmpty)return;final tags=g.text.split(',').map((e)=>e.trim()).where((e)=>e.isNotEmpty).toList();Entry? created;if(old==null){created=Entry(id:uid(),title:t.text.trim(),description:d.text.trim(),category:cat,date:date,reminder:rem,task:task,tags:tags,follows:[]);setState(()=>items.add(created!));}else{old.title=t.text.trim();old.description=d.text.trim();old.category=cat;old.date=date;old.reminder=rem;old.tags=tags;}if(rem!=null)await scheduleReminder((old??created!).id.hashCode,t.text.trim(),task?'یادآوری کار':'یادآوری یادداشت',rem!);await save();if(c.mounted)Navigator.pop(c);},child:const Text('ذخیره'))]))));}
void details(Entry e)=>Navigator.push(context,MaterialPageRoute(builder:(_)=>Details(e:e,onEdit:()=>edit(old:e,task:e.task),onChange:(){setState((){});save();},onFollow:()=>addFollow(e))));
Future<void>addFollow(Entry e)async{final t=TextEditingController();DateTime? rem;await showDialog(context:context,builder:(_)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('ثبت پیگیری'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:t,maxLines:4,decoration:const InputDecoration(labelText:'شرح پیگیری')),ListTile(leading:const Icon(Icons.notifications_active_outlined),title:Text(rem==null?'افزودن یادآوری پیگیری':'یادآوری: ${jdate(rem!)} ${jtime(rem!)}'),onTap:()async{final day=await showDatePicker(context:c,firstDate:DateTime.now(),lastDate:DateTime(2100),initialDate:DateTime.now());if(day==null)return;final tm=await showTimePicker(context:c,initialTime:TimeOfDay.now());if(tm!=null)set(()=>rem=DateTime(day.year,day.month,day.day,tm.hour,tm.minute));})]),actions:[TextButton(onPressed:()async{if(t.text.trim().isEmpty){Navigator.pop(c);return;}final f=Follow(t.text.trim(),DateTime.now(),reminder:rem);setState(()=>e.follows.add(f));if(rem!=null)await scheduleReminder('${e.id}${e.follows.length}'.hashCode,e.title,'یادآوری پیگیری: ${f.text}',rem!);await save();if(c.mounted)Navigator.pop(c);},child:const Text('ثبت'))])));}
void menu()=>showModalBottomSheet(context:context,builder:(_)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[for(final f in ['امروز','آینده','عقب‌افتاده','یادداشت‌ها','کارها','بایگانی'])ListTile(title:Text(f),leading:const Icon(Icons.folder_open),onTap:(){setState(()=>filter=f);Navigator.pop(context);}),ListTile(title:const Text('دسته‌بندی‌ها'),leading:const Icon(Icons.category),onTap:(){Navigator.pop(context);catDialog();}),ListTile(title:const Text('حالت تاریک / روشن'),leading:const Icon(Icons.dark_mode),onTap:(){Navigator.pop(context);widget.toggle();})]));
