@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text('آروین • $filter'),actions:[IconButton(icon:const Icon(Icons.search),onPressed:()=>showSearch(context:c,delegate:SearchItems(items))),IconButton(icon:const Icon(Icons.sort),onPressed:()=>showModalBottomSheet(context:c,builder:(_)=>Column(mainAxisSize:MainAxisSize.min,children:['آخرین وارده','تاریخ','عنوان'].map((s)=>ListTile(title:Text(s),onTap:(){setState((){if(sort==s)reverse=!reverse;else{sort=s;reverse=false;}});Navigator.pop(c);})).toList()))),IconButton(icon:const Icon(Icons.menu),onPressed:menu)]),body:shown.isEmpty?const Center(child:Text('هنوز موردی ثبت نشده است')):ListView.builder(padding:const EdgeInsets.only(bottom:90),itemCount:shown.length,itemBuilder:(_,i){final e=shown[i];return Dismissible(key:ValueKey(e.id),background:const Align(alignment:Alignment.centerRight,child:Padding(padding:EdgeInsets.all(20),child:Icon(Icons.today))),secondaryBackground:const Align(alignment:Alignment.centerLeft,child:Padding(padding:EdgeInsets.all(20),child:Icon(Icons.delete))),confirmDismiss:(d)async{if(d==DismissDirection.startToEnd){setState(()=>e.date=DateTime.now());await save();return false;}setState(()=>e.trash=true);await save();return true;},child:Card(child:ListTile(onTap:()=>details(e),leading:CircleAvatar(child:Icon(e.task?Icons.task_alt:Icons.note)),title:Text(e.title,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${e.category} • ${e.follows.isEmpty?'بدون پیگیری':'آخرین پیگیری ${jtime(e.follows.last.at)}'}${e.reminder==null?'':' • یادآوری ${jtime(e.reminder!)}'}\n${jdate(e.date)} • ${jtime(e.date)}',maxLines:2),isThreeLine:true,trailing:e.task?IconButton(icon:const Icon(Icons.add_task),onPressed:()=>addFollow(e)):null)));}),floatingActionButton:FloatingActionButton(onPressed:()=>showModalBottomSheet(context:c,builder:(_)=>Wrap(children:[ListTile(leading:const Icon(Icons.note_add),title:const Text('یادداشت جدید'),onTap:(){Navigator.pop(c);edit(task:false);}),ListTile(leading:const Icon(Icons.add_task),title:const Text('کار جدید'),onTap:(){Navigator.pop(c);edit(task:true);})])),child:const Icon(Icons.add)));
