class SearchItems extends SearchDelegate<Entry?>{final List<Entry>items;SearchItems(this.items);@override List<Widget>? buildActions(BuildContext c)=>[IconButton(icon:const Icon(Icons.clear),onPressed:()=>query='')];@override Widget? buildLeading(BuildContext c)=>IconButton(icon:const Icon(Icons.arrow_back),onPressed:()=>close(c,null));@override Widget buildResults(BuildContext c)=>ListView(children:items.where((x)=>x.title.contains(query)||x.description.contains(query)||x.category.contains(query)||x.tags.any((t)=>t.contains(query))).map((x)=>ListTile(title:Text(x.title),subtitle:Text(x.description))).toList());@override Widget buildSuggestions(BuildContext c)=>buildResults(c);}
